   224  static gboolean
   225  g_uri_char_is_unreserved (gchar ch)
   226  {
   227    if (g_ascii_isalnum (ch))
   228      return TRUE;
   229    return ch == '-' || ch == '.' || ch == '_' || ch == '~';
   230  }
