   232  #define XDIGIT(c) ((c) <= '9' ? (c) - '0' : ((c) & 0x4F) - 'A' + 10)
   233  #define HEXCHAR(s) ((XDIGIT (s[1]) << 4) + XDIGIT (s[2]))
   234
   235  static gssize
   236  uri_decoder (gchar       **out,
   237               const gchar  *start,
   238               gsize         length,
   239               gboolean      just_normalize,
   240               GUriFlags     flags,
   241               GUriError     parse_error,
   242               GError      **error)
   243  {
   244    gchar *decoded, *d, c;
   245    const gchar *invalid, *s, *end;
   246    gssize len;
   247
   248    if (!(flags & G_URI_FLAGS_ENCODED))
   249      just_normalize = FALSE;
   250
   251    decoded = g_malloc (length + 1);
   252    for (s = start, end = s + length, d = decoded; s < end; s++)
   253      {
   254        if (*s == '%')
   255          {
   256            if (!g_ascii_isxdigit (s[1]) ||
   257                !g_ascii_isxdigit (s[2]))
   258              {
   259                /* % followed by non-hex; this is an error */
   260                if (flags & G_URI_FLAGS_PARSE_STRICT)
   261                  {
   262                    g_set_error_literal (error, G_URI_ERROR, parse_error,
   263                                         _("Invalid %-encoding in URI"));
   264                    g_free (decoded);
   265                    return -1;
   266                  }
   267
   268                /* In non-strict mode, just let it through; we *don't*
   269                 * fix it to "%25", since that might change the way that
   270                 * the URI's owner would interpret it.
   271                 */
   272                *d++ = *s;
   273                continue;
   274              }
   275
   276            c = HEXCHAR (s);
   277            if (just_normalize && !g_uri_char_is_unreserved (c))
   278              {
   279                /* Leave the % sequence there. */
   280                *d++ = *s;
   281              }
   282            else
   283              {
   284                *d++ = c;
   285                s += 2;
   286              }
   287          }
   288        else
   289          *d++ = *s;
   290      }
   291    *d = '\0';
   292
   293    len = d - decoded;
   294
   295    if (!(flags & G_URI_FLAGS_ENCODED) &&
   296        !g_utf8_validate (decoded, len, &invalid))
   297      {
   298        g_set_error_literal (error, G_URI_ERROR, parse_error,
   299                             _("Non-UTF-8 characters in URI"));
   300        g_free (decoded);
   301        return -1;
   302      }
   303
   304    if (out)
   305      *out = g_steal_pointer (&decoded);
   306
   307    g_free (decoded);
   308    return len;
   309  }
