   311  static gboolean
   312  uri_decode (gchar       **out,
   313              const gchar  *start,
   314              gsize         length,
   315              GUriFlags     flags,
   316              GUriError     parse_error,
   317              GError      **error)
   318  {
   319    return uri_decoder (out, start, length, FALSE, flags,
   320                        parse_error, error) != -1;
   321  }
