   335  static gboolean
   336  is_valid (guchar       c,
   337            const gchar *reserved_chars_allowed)
   338  {
   339    if (g_uri_char_is_unreserved (c))
   340      return TRUE;
   341
   342    if (reserved_chars_allowed && strchr (reserved_chars_allowed, c))
   343      return TRUE;
   344
   345    return FALSE;
   346  }
